const err = $input.first().json;

const workflowName = err.workflow?.name || 'غير معروف';
const nodeName     = err.execution?.lastNodeExecuted || 'غير معروف';
const errorMsg     = err.execution?.error?.message || 'لا يوجد تفاصيل';
const errorStack   = err.execution?.error?.stack || '';
const execId       = err.execution?.id || '';
const execUrl      = `https://babylonai.me/workflow/${err.workflow?.id}/executions/${execId}`;

// أول 300 حرف من الـ stack trace
const stackShort = errorStack.substring(0, 300).replace(/</g, '&lt;').replace(/>/g, '&gt;');

const text = [
  `🚨 <b>خطأ في الـ Workflow</b>`,
  `━━━━━━━━━━━━━━━━━━━━`,
  `📋 <b>الـ Workflow:</b> ${workflowName}`,
  `🔴 <b>العقدة الأخيرة:</b> ${nodeName}`,
  `❌ <b>الخطأ:</b> ${errorMsg}`,
  stackShort ? `\n<pre>${stackShort}</pre>` : '',
  `━━━━━━━━━━━━━━━━━━━━`,
  `🔗 <a href="${execUrl}">عرض التنفيذ</a>`
].filter(Boolean).join('\n');

const telegramBody = JSON.stringify({
  chat_id: '-5006780541',
  text: text,
  parse_mode: 'HTML',
  disable_web_page_preview: true
});

return [{ json: { telegramBody, workflowName, nodeName, errorMsg } }];
